    se, x, fin = [1] * (n + 1), 1, [0] * n
    while x != len(se):
        se[x], jj, curr, inde, vals = 0, 0, [x], [x - 1], [p[x - 1]]
        while jj != len(curr):
            zz = curr[jj]
            for y in path[zz]:
                if se[y]:
                    curr.append(y)
                    inde.append(y-1)
                    vals.append(p[y-1])
                    se[y] = 0
            jj += 1
        inde.sort()
        vals.sort()
        for ind, i in enumerate(inde):
            fin[i] = vals[-ind - 1]
        while x != n + 1 and not se[x]:
            x += 1
    for i in fin:
