from bisect import insort, bisect_right, bisect_left

class Multi_map:
    def __init__(self):
        self.mm = dict()
        self.lr = []

    def insert(self, x, y):
        if x in self.mm:
            self.mm[x].append(y)
        else:
            self.mm[x] = [y]
            insort(self.lr, x)

    def get(self, x):
        if x in self.mm and self.mm[x] != []:
            print(*self.mm[x], sep='\n')

    def delete(self, x):
        if x in self.mm:
            self.mm[x] = []

    def dump(self, l, r):
        lb = bisect_left(self.lr, l)
        ub = bisect_right(self.lr, r)
        for i in range(lb, ub):
            k = self.lr[i]
            for v in self.mm[k]:
                print(f'{k} {v}')


