from sys import stdin,stdout

class Tree(object):
    def __init__(self,n):
        self.tree=[0]*(4*n+10)
        self.b=[0]*(n+10)
        self.a=list(map(int,stdin.readline().split()))
        self.n=n
    def update(self,L,C,l,r,rt):
        if l==r:
            self.tree[rt]+=C
            return
        mid=(l+r)//2
        if L<=mid:
            self.update(L,C,l,mid,rt<<1)
        else:
            self.update(L,C,mid+1,r,rt<<1|1)
        self.tree[rt]=self.tree[rt<<1]+self.tree[rt<<1|1]


    def query(self,s,l,r,rt):
        if l==r:
            return l
        mid=(l+r)//2
        if self.tree[rt<<1]>s:
            return self.query(s,l,mid,rt<<1)
        else:
            return self.query(s-self.tree[rt<<1],mid+1,r,rt<<1|1)
    def slove(self):

        for i in range(n):
            self.update(i+1,i+1,1,n,1)
        for i in range(n,0,-1):
            self.b[i]=self.query(self.a[i-1],1,n,1)
            self.update(self.b[i],-self.b[i],1,n,1)
        for i in range(n):
            stdout.write('%d '%(self.b[i+1]))




if __name__ == '__main__':
    n=int(stdin.readline())
    seg=Tree(n)
    seg.slove()

import sys

border = 1 << 30


def build(x=0):
    res = [0, 0]

    i = 0
    while x and i < 30:
        if x & 1:
            res[1] += (1 << i)
        x >>= 1
        i += 1

    i = 0
    while x:
        if x & 1:
            res[0] += (1 << i)
        x >>= 1
        i += 1

    return res


n, r, k = map(int, sys.stdin.buffer.readline().decode('utf-8').split())
a = list(map(int, sys.stdin.buffer.readline().decode('utf-8').split()))

k_big, k_small = build(k)
left = build(sum(a[:r]))
minus_big, minus_small = [0]*n, [0]*n
w = 2*r+1


def solve(level_big, level_small):
    used_big = used_small = 0
    acc_big, acc_small = left

    for i in range(n):
        if minus_small[i] or minus_big[i]:
            acc_big -= minus_big[i]
            acc_small -= minus_small[i]
            if acc_small < 0:
                acc_small += border
                acc_big -= 1
            elif acc_small >= border:
                acc_small -= border
                acc_big += 1

            minus_big[i] = minus_small[i] = 0

        acc_small += (a[i+r] if i+r < n else 0) - (a[i-r-1] if i-r >= 1 else 0)
        if acc_small >= border:
            acc_small -= border
            acc_big += 1
        elif acc_small < 0:
            acc_small += border
            acc_big -= 1

        if acc_big < level_big or acc_big == level_big and acc_small < level_small:
            used_big += level_big - acc_big
            used_small += level_small - acc_small
            if used_small >= border:
                used_small -= border
                used_big += 1
            elif used_small < 0:
                used_small += border
                used_big -= 1

            if used_big > k_big or used_big == k_big and used_small > k_small:
                break
            if i+w < n:
                minus_big[i+w] = level_big - acc_big
                minus_small[i+w] = level_small - acc_small

            acc_big = level_big
            acc_small = level_small

    for i in range(i+1, n):
        if minus_small[i] or minus_big[i]:
            minus_small[i] = minus_big[i] = 0

    return used_big < k_big or used_big == k_big and used_small <= k_small


